work=Path('build/review-j18-profile').resolve(); target=Path('docs/review-performance/J18.json')
frozen=Path('build/review-j12-performance-inputs').resolve()
data={'parent_commit':'06a671d','parent_code_commit':'f723699','protocol':'CPU0, seed7, 3 alternating pairs. At least 20% median wall/internal query time or 25% median RSS triggers 5 further pairs; confirmed regression stops the run. No concurrent own builds/tests. All parent/candidate queries and match results must agree. Small-query workloads calibrated on parent to about 150ms then fixed for both versions. Instrumented profile is attribution only, not speed comparison. lookup_seconds includes legal-action and probability validation, plus backend reading; generation excludes nested encoding. Clock instrumentation adds overhead.','query_runs':[],'profiles':{},'runs':[],'summary':[],'blocked':None}
def digest(path):
 with open(path,'rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def save():
 data['script']=Path(__file__).read_text();data['prepare_script']=Path('/tmp/mus-j18-prepare-profile.py').read_text()
 data['harness_source']=(work/'harness.c').read_text();data['codec_differential_source']=(work/'codec-differential.c').read_text()
