 rows=[json.loads(line) for line in execute([work/(version+'-profile'),'1000'])[0].splitlines()]
 data['profiles'][version]=rows
for a,b in zip(data['profiles']['parent'],data['profiles']['candidate']):
 assert key(a)==key(b) and a['checksum']==b['checksum'] and a['lookups']==b['lookups']
save()
def query_pair(repeat):
 for version in (('parent','candidate') if repeat%2 else ('candidate','parent')):
  command=[work/version,'0',work/'plan.txt'];out,wall,rss=execute(command)
  rows=[json.loads(line) for line in out.splitlines()]
