  assert [(key(r),r['checksum'],r['iterations']) for r in rows]==[(key(r),r['checksum'],r['iterations']) for r in reference]
  data['query_runs'].append({'version':version,'repeat':repeat,'command':list(map(str,command)),'wall_seconds':wall,'peak_rss_kib':rss,'cases':rows})
  save();print('queries',version,repeat,round(wall,3),rss,flush=True)
def query_summary(confirm=False):
 runs=[r for r in data['query_runs'] if (r['repeat']>3)==confirm];summaries=[];trigger=False
 for i in range(len(plan)):
  a=statistics.median(r['cases'][i]['seconds'] for r in runs if r['version']=='parent');b=statistics.median(r['cases'][i]['seconds'] for r in runs if r['version']=='candidate')
  change=100*(b/a-1); trigger |= change>=20
  summaries.append({'case':key(runs[0]['cases'][i]),'parent_seconds':a,'candidate_seconds':b,'change_percent':change})
 rss_a=statistics.median(r['peak_rss_kib'] for r in runs if r['version']=='parent');rss_b=statistics.median(r['peak_rss_kib'] for r in runs if r['version']=='candidate')
 trigger |= rss_b/rss_a>=1.25
