#include <inttypes.h>
#define main fixture_main
#include "../../tests/test_mus_adapter.c"
#undef main
static uint64_t hash = 7, calls, valid;
static void visit(MusOrdagoInformationSet info) {
    for (int format = 0; format < 3; ++format) {
        InfoSetKey key = 42;
        info.score_enabled = format == 2;
        Status status = format == 2 ? mus_score_game_information_set_encode(&info, 40, &key)
            : format == 1 ? mus_ordago_public_game_information_set_encode(&info, &key)
                          : mus_ordago_game_information_set_encode(&info, &key);
        hash = hash * 31 + (uint64_t)status;
        hash = hash * 31 + (uint64_t)key;
        ++calls; valid += status == CFR_STATUS_SUCCESS;
        if (status != CFR_STATUS_SUCCESS && key != 42) ++failures;
    }
}
int main(void) {
    const MusGamePhase phases[] = {MUS_PHASE_MUS_PLAYER_0, MUS_PHASE_GRANDE,
        MUS_PHASE_CHICA, MUS_PHASE_PARES, MUS_PHASE_JUEGO, MUS_PHASE_PUNTO};
    const int values[] = {-2147483647-1, -1, 0, 1, 3, 4, 7, 8, 30, 31, 32, 33, 37, 38, 40, 41, 255, 2147483647};
    for (int a=0;a<8;++a) for(int b=a;b<8;++b) for(int c=b;c<8;++c) for(int d=c;d<8;++d) {
        uint8_t cards[8]={0}; ++cards[a];++cards[b];++cards[c];++cards[d];
        for (size_t phase=0;phase<sizeof(phases)/sizeof(phases[0]);++phase) {
            MusOrdagoInformationSet base=info_base(phases[phase],CFR_PLAYER_0);
            if (mus_ordago_game_information_set_set_hand(&base,cards)!=CFR_STATUS_SUCCESS) continue;
            visit(base);
            for (size_t v=0;v<sizeof(values)/sizeof(values[0]);++v) for(int field=0;field<13;++field) {
                MusOrdagoInformationSet info=base; int x=values[v];
                switch(field) {
                case 0: info.king_count=(uint8_t)x;break;
                case 1: info.highest_non_king=(MusCardClass)x;break;
                case 2: info.has_highest_non_king=(bool)x;break;
                case 3: info.pito_count=(uint8_t)x;break;
                case 4: info.lowest_non_pito=(MusCardClass)x;break;
                case 5: info.has_lowest_non_pito=(bool)x;break;
                case 6: info.pairs_type=(MusPairsType)x;break;
                case 7: info.pairs_value=(MusCardClass)x;break;
                case 8: info.second_pairs_value=(MusCardClass)x;break;
                case 9: info.has_second_pairs_value=(bool)x;break;
                case 10: info.game_value=(uint8_t)x;break;
                case 11: info.point_value=(uint8_t)x;break;
                case 12: memset(info.hand,(unsigned char)x,sizeof(info.hand));break;
                }
                visit(info);
            }
        }
    }
    printf("calls=%"PRIu64" valid=%"PRIu64" hash=%"PRIu64" failures=%d\n",calls,valid,hash,failures);
    return failures ? 1 : 0;
}

